(1559, 161, '_page_builder_4_faq_description', 'field_6aa44c59ae1d4'),
(1560, 161, 'page_builder_4_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(1561, 161, '_page_builder_4_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(1562, 161, 'page_builder_4_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(1563, 161, '_page_builder_4_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
