INSERT INTO `asc_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(1566, 161, 'page_builder_4_faq_items_1_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.</div>\r\n</div>\r\n</div>'),
(1567, 161, '_page_builder_4_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(1568, 161, 'page_builder_4_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(1569, 161, '_page_builder_4_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(1570, 161, 'page_builder_4_faq_items_2_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.</div>\r\n</div>\r\n</div>'),
(1571, 161, '_page_builder_4_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(1572, 161, 'page_builder_4_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(1573, 161, '_page_builder_4_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(1574, 161, 'page_builder_4_faq_items_3_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.</div>\r\n</div>\r\n</div>'),
(1575, 161, '_page_builder_4_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(1576, 161, 'page_builder_4_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(1577, 161, '_page_builder_4_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(1578, 161, 'page_builder_4_faq_items_4_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.</div>\r\n</div>\r\n</div>'),
(1579, 161, '_page_builder_4_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(1580, 161, 'page_builder_4_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(1581, 161, '_page_builder_4_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(1582, 161, 'page_builder_4_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(1583, 161, '_page_builder_4_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
(1584, 161, 'page_builder_4_faq_items', '6'),
