(1723, 174, '_page_builder_1_story_title', 'field_6aa42919433a2'),
(1724, 174, 'page_builder_1_story_description', 'Asal Canning Center was established on September 18, 2000 in Paldi, Ahmedabad with a clear mission: to bridge the gap between fresh agricultural harvest and long-term, pure natural preservation.\r\n\r\nOur center provides food-grade pulp extraction, tin canning, glass jar sealing, and retort pouch packing for households, farmers, and commercial brands alike with zero compromise on thermal sterilization standards.'),
(1725, 174, '_page_builder_1_story_description', 'field_6aa42930433a3'),
(1726, 174, 'page_builder_1_story_values_0_value_icon', 'fa-solid fa-certificate'),
