(2442, 196, 'page_builder_4_faq_tag', 'Client Queries'),
(2443, 196, '_page_builder_4_faq_tag', 'field_6aa44c3bae1d2'),
(2444, 196, 'page_builder_4_faq_title', 'Frequently Asked Questions'),
(2445, 196, '_page_builder_4_faq_title', 'field_6aa44c49ae1d3'),
(2446, 196, 'page_builder_4_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(2447, 196, '_page_builder_4_faq_description', 'field_6aa44c59ae1d4'),
(2448, 196, 'page_builder_4_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(2449, 196, '_page_builder_4_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(2450, 196, 'page_builder_4_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(2451, 196, '_page_builder_4_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(2452, 196, 'page_builder_4_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(2453, 196, '_page_builder_4_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(2454, 196, 'page_builder_4_faq_items_1_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.</div>\r\n</div>\r\n</div>'),
(2455, 196, '_page_builder_4_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(2456, 196, 'page_builder_4_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(2457, 196, '_page_builder_4_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(2458, 196, 'page_builder_4_faq_items_2_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.</div>\r\n</div>\r\n</div>'),
(2459, 196, '_page_builder_4_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(2460, 196, 'page_builder_4_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(2461, 196, '_page_builder_4_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(2462, 196, 'page_builder_4_faq_items_3_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.</div>\r\n</div>\r\n</div>'),
(2463, 196, '_page_builder_4_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(2464, 196, 'page_builder_4_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(2465, 196, '_page_builder_4_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(2466, 196, 'page_builder_4_faq_items_4_faq_answer', '<div class=\"faq-item active\">\r\n<div class=\"faq-body\">\r\n<div class=\"faq-content\">Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.</div>\r\n</div>\r\n</div>'),
(2467, 196, '_page_builder_4_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(2468, 196, 'page_builder_4_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(2469, 196, '_page_builder_4_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(2470, 196, 'page_builder_4_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(2471, 196, '_page_builder_4_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
