(4997, 377, 'page_builder_4_faq_tag', 'Client Queries'),
(4998, 377, '_page_builder_4_faq_tag', 'field_6aa44c3bae1d2'),
(4999, 377, 'page_builder_4_faq_title', 'Frequently Asked Questions'),
(5000, 377, '_page_builder_4_faq_title', 'field_6aa44c49ae1d3'),
(5001, 377, 'page_builder_4_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(5002, 377, '_page_builder_4_faq_description', 'field_6aa44c59ae1d4'),
(5003, 377, 'page_builder_4_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(5004, 377, '_page_builder_4_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(5005, 377, 'page_builder_4_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(5006, 377, '_page_builder_4_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(5007, 377, 'page_builder_4_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(5008, 377, '_page_builder_4_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(5009, 377, 'page_builder_4_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(5010, 377, '_page_builder_4_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(5011, 377, 'page_builder_4_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(5012, 377, '_page_builder_4_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(5013, 377, 'page_builder_4_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(5014, 377, '_page_builder_4_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(5015, 377, 'page_builder_4_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(5016, 377, '_page_builder_4_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(5017, 377, 'page_builder_4_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(5018, 377, '_page_builder_4_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(5019, 377, 'page_builder_4_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(5020, 377, '_page_builder_4_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(5021, 377, 'page_builder_4_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(5022, 377, '_page_builder_4_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(5023, 377, 'page_builder_4_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(5024, 377, '_page_builder_4_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(5025, 377, 'page_builder_4_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(5026, 377, '_page_builder_4_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
(5027, 377, 'page_builder_4_faq_items', '6'),
