INSERT INTO `asc_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(5332, 383, '_page_builder_3_process_steps_0_step_description', 'field_6aa44ab621cfc'),
(5333, 383, 'page_builder_3_process_steps_1_step_number', '02'),
(5334, 383, '_page_builder_3_process_steps_1_step_number', 'field_6aa44a9521cfa'),
(5335, 383, 'page_builder_3_process_steps_1_step_title', 'Sterile Cold Pulping'),
(5336, 383, '_page_builder_3_process_steps_1_step_title', 'field_6aa44aa821cfb'),
(5337, 383, 'page_builder_3_process_steps_1_step_description', 'Mechanical pulp extraction under sterile cold-process without added synthetic colors or water dilution.'),
(5338, 383, '_page_builder_3_process_steps_1_step_description', 'field_6aa44ab621cfc'),
(5339, 383, 'page_builder_3_process_steps_2_step_number', '03'),
(5340, 383, '_page_builder_3_process_steps_2_step_number', 'field_6aa44a9521cfa'),
(5341, 383, 'page_builder_3_process_steps_2_step_title', 'Thermal Pasteurization'),
(5342, 383, '_page_builder_3_process_steps_2_step_title', 'field_6aa44aa821cfb'),
(5343, 383, 'page_builder_3_process_steps_2_step_description', 'Controlled thermal processing eliminating microbial activity while preserving natural fruit aroma.'),
(5344, 383, '_page_builder_3_process_steps_2_step_description', 'field_6aa44ab621cfc'),
(5345, 383, 'page_builder_3_process_steps_3_step_number', '04'),
(5346, 383, '_page_builder_3_process_steps_3_step_number', 'field_6aa44a9521cfa'),
(5347, 383, 'page_builder_3_process_steps_3_step_title', 'Hermetic Seaming'),
(5348, 383, '_page_builder_3_process_steps_3_step_title', 'field_6aa44aa821cfb'),
(5349, 383, 'page_builder_3_process_steps_3_step_description', 'Vacuum double-seam tin capping or retort pouch sealing for long-term ambient shelf life.'),
(5350, 383, '_page_builder_3_process_steps_3_step_description', 'field_6aa44ab621cfc'),
(5351, 383, 'page_builder_3_process_steps', '4'),
(5352, 383, '_page_builder_3_process_steps', 'field_6aa44a8821cf9'),
(5353, 383, 'page_builder_4_faq_tag', 'Client Queries'),
(5354, 383, '_page_builder_4_faq_tag', 'field_6aa44c3bae1d2'),
(5355, 383, 'page_builder_4_faq_title', 'Frequently Asked Questions'),
(5356, 383, '_page_builder_4_faq_title', 'field_6aa44c49ae1d3'),
(5357, 383, 'page_builder_4_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(5358, 383, '_page_builder_4_faq_description', 'field_6aa44c59ae1d4'),
(5359, 383, 'page_builder_4_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(5360, 383, '_page_builder_4_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(5361, 383, 'page_builder_4_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(5362, 383, '_page_builder_4_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(5363, 383, 'page_builder_4_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(5364, 383, '_page_builder_4_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(5365, 383, 'page_builder_4_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(5366, 383, '_page_builder_4_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(5367, 383, 'page_builder_4_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(5368, 383, '_page_builder_4_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(5369, 383, 'page_builder_4_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(5370, 383, '_page_builder_4_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(5371, 383, 'page_builder_4_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(5372, 383, '_page_builder_4_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(5373, 383, 'page_builder_4_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(5374, 383, '_page_builder_4_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(5375, 383, 'page_builder_4_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(5376, 383, '_page_builder_4_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(5377, 383, 'page_builder_4_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(5378, 383, '_page_builder_4_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(5379, 383, 'page_builder_4_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(5380, 383, '_page_builder_4_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(5381, 383, 'page_builder_4_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(5382, 383, '_page_builder_4_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
