(6049, 384, 'page_builder_4_process_tag', 'Standard Workflow'),
(6050, 384, '_page_builder_4_process_tag', 'field_6aa44a4f21cf6'),
(6051, 384, 'page_builder_4_process_title', 'Our 4-Step Canning Process'),
(6052, 384, '_page_builder_4_process_title', 'field_6aa44a6921cf7'),
(6053, 384, 'page_builder_4_process_description', 'Ensuring zero micro-flora activity and maximum natural nutrition retention.'),
(6054, 384, '_page_builder_4_process_description', 'field_6aa44a7621cf8'),
(6055, 384, 'page_builder_4_process_steps_0_step_number', '01'),
(6056, 384, '_page_builder_4_process_steps_0_step_number', 'field_6aa44a9521cfa'),
(6057, 384, 'page_builder_4_process_steps_0_step_title', 'Harvesting & Brix Inspection'),
(6058, 384, '_page_builder_4_process_steps_0_step_title', 'field_6aa44aa821cfb'),
(6059, 384, 'page_builder_4_process_steps_0_step_description', 'Hand-picked farm fresh fruit selection evaluated for peak maturity and natural Brix sweetness.'),
(6060, 384, '_page_builder_4_process_steps_0_step_description', 'field_6aa44ab621cfc'),
(6061, 384, 'page_builder_4_process_steps_1_step_number', '02'),
(6062, 384, '_page_builder_4_process_steps_1_step_number', 'field_6aa44a9521cfa'),
(6063, 384, 'page_builder_4_process_steps_1_step_title', 'Sterile Cold Pulping'),
(6064, 384, '_page_builder_4_process_steps_1_step_title', 'field_6aa44aa821cfb'),
(6065, 384, 'page_builder_4_process_steps_1_step_description', 'Mechanical pulp extraction under sterile cold-process without added synthetic colors or water dilution.'),
(6066, 384, '_page_builder_4_process_steps_1_step_description', 'field_6aa44ab621cfc'),
(6067, 384, 'page_builder_4_process_steps_2_step_number', '03'),
(6068, 384, '_page_builder_4_process_steps_2_step_number', 'field_6aa44a9521cfa'),
(6069, 384, 'page_builder_4_process_steps_2_step_title', 'Thermal Pasteurization'),
(6070, 384, '_page_builder_4_process_steps_2_step_title', 'field_6aa44aa821cfb'),
(6071, 384, 'page_builder_4_process_steps_2_step_description', 'Controlled thermal processing eliminating microbial activity while preserving natural fruit aroma.'),
(6072, 384, '_page_builder_4_process_steps_2_step_description', 'field_6aa44ab621cfc'),
(6073, 384, 'page_builder_4_process_steps_3_step_number', '04'),
(6074, 384, '_page_builder_4_process_steps_3_step_number', 'field_6aa44a9521cfa'),
(6075, 384, 'page_builder_4_process_steps_3_step_title', 'Hermetic Seaming'),
(6076, 384, '_page_builder_4_process_steps_3_step_title', 'field_6aa44aa821cfb'),
(6077, 384, 'page_builder_4_process_steps_3_step_description', 'Vacuum double-seam tin capping or retort pouch sealing for long-term ambient shelf life.'),
(6078, 384, '_page_builder_4_process_steps_3_step_description', 'field_6aa44ab621cfc'),
(6079, 384, 'page_builder_4_process_steps', '4'),
(6080, 384, '_page_builder_4_process_steps', 'field_6aa44a8821cf9'),
(6081, 384, 'page_builder_5_faq_tag', 'Client Queries'),
(6082, 384, '_page_builder_5_faq_tag', 'field_6aa44c3bae1d2'),
(6083, 384, 'page_builder_5_faq_title', 'Frequently Asked Questions'),
(6084, 384, '_page_builder_5_faq_title', 'field_6aa44c49ae1d3'),
(6085, 384, 'page_builder_5_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(6086, 384, '_page_builder_5_faq_description', 'field_6aa44c59ae1d4'),
(6087, 384, 'page_builder_5_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(6088, 384, '_page_builder_5_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(6089, 384, 'page_builder_5_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(6090, 384, '_page_builder_5_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(6091, 384, 'page_builder_5_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(6092, 384, '_page_builder_5_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(6093, 384, 'page_builder_5_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(6094, 384, '_page_builder_5_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(6095, 384, 'page_builder_5_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(6096, 384, '_page_builder_5_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(6097, 384, 'page_builder_5_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(6098, 384, '_page_builder_5_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(6099, 384, 'page_builder_5_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(6100, 384, '_page_builder_5_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(6101, 384, 'page_builder_5_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(6102, 384, '_page_builder_5_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(6103, 384, 'page_builder_5_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(6104, 384, '_page_builder_5_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(6105, 384, 'page_builder_5_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(6106, 384, '_page_builder_5_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(6107, 384, 'page_builder_5_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(6108, 384, '_page_builder_5_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(6109, 384, 'page_builder_5_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(6110, 384, '_page_builder_5_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
