(6660, 385, '_page_builder_3_process_tag', 'field_6aa44a4f21cf6'),
(6661, 385, 'page_builder_3_process_title', 'Our 4-Step Canning Process'),
(6662, 385, '_page_builder_3_process_title', 'field_6aa44a6921cf7'),
(6663, 385, 'page_builder_3_process_description', 'Ensuring zero micro-flora activity and maximum natural nutrition retention.'),
(6664, 385, '_page_builder_3_process_description', 'field_6aa44a7621cf8'),
(6665, 385, 'page_builder_3_process_steps_0_step_number', '01'),
(6666, 385, '_page_builder_3_process_steps_0_step_number', 'field_6aa44a9521cfa'),
(6667, 385, 'page_builder_3_process_steps_0_step_title', 'Harvesting & Brix Inspection'),
(6668, 385, '_page_builder_3_process_steps_0_step_title', 'field_6aa44aa821cfb'),
(6669, 385, 'page_builder_3_process_steps_0_step_description', 'Hand-picked farm fresh fruit selection evaluated for peak maturity and natural Brix sweetness.'),
(6670, 385, '_page_builder_3_process_steps_0_step_description', 'field_6aa44ab621cfc'),
(6671, 385, 'page_builder_3_process_steps_1_step_number', '02'),
(6672, 385, '_page_builder_3_process_steps_1_step_number', 'field_6aa44a9521cfa'),
(6673, 385, 'page_builder_3_process_steps_1_step_title', 'Sterile Cold Pulping'),
(6674, 385, '_page_builder_3_process_steps_1_step_title', 'field_6aa44aa821cfb'),
(6675, 385, 'page_builder_3_process_steps_1_step_description', 'Mechanical pulp extraction under sterile cold-process without added synthetic colors or water dilution.'),
(6676, 385, '_page_builder_3_process_steps_1_step_description', 'field_6aa44ab621cfc'),
(6677, 385, 'page_builder_3_process_steps_2_step_number', '03'),
(6678, 385, '_page_builder_3_process_steps_2_step_number', 'field_6aa44a9521cfa'),
(6679, 385, 'page_builder_3_process_steps_2_step_title', 'Thermal Pasteurization'),
(6680, 385, '_page_builder_3_process_steps_2_step_title', 'field_6aa44aa821cfb'),
(6681, 385, 'page_builder_3_process_steps_2_step_description', 'Controlled thermal processing eliminating microbial activity while preserving natural fruit aroma.'),
(6682, 385, '_page_builder_3_process_steps_2_step_description', 'field_6aa44ab621cfc'),
(6683, 385, 'page_builder_3_process_steps_3_step_number', '04'),
(6684, 385, '_page_builder_3_process_steps_3_step_number', 'field_6aa44a9521cfa'),
(6685, 385, 'page_builder_3_process_steps_3_step_title', 'Hermetic Seaming'),
(6686, 385, '_page_builder_3_process_steps_3_step_title', 'field_6aa44aa821cfb'),
(6687, 385, 'page_builder_3_process_steps_3_step_description', 'Vacuum double-seam tin capping or retort pouch sealing for long-term ambient shelf life.'),
(6688, 385, '_page_builder_3_process_steps_3_step_description', 'field_6aa44ab621cfc'),
(6689, 385, 'page_builder_3_process_steps', '4'),
(6690, 385, '_page_builder_3_process_steps', 'field_6aa44a8821cf9'),
(6691, 385, 'page_builder_4_faq_tag', 'Client Queries'),
(6692, 385, '_page_builder_4_faq_tag', 'field_6aa44c3bae1d2'),
(6693, 385, 'page_builder_4_faq_title', 'Frequently Asked Questions'),
(6694, 385, '_page_builder_4_faq_title', 'field_6aa44c49ae1d3'),
(6695, 385, 'page_builder_4_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(6696, 385, '_page_builder_4_faq_description', 'field_6aa44c59ae1d4'),
(6697, 385, 'page_builder_4_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(6698, 385, '_page_builder_4_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(6699, 385, 'page_builder_4_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(6700, 385, '_page_builder_4_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(6701, 385, 'page_builder_4_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(6702, 385, '_page_builder_4_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(6703, 385, 'page_builder_4_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(6704, 385, '_page_builder_4_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(6705, 385, 'page_builder_4_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(6706, 385, '_page_builder_4_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(6707, 385, 'page_builder_4_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(6708, 385, '_page_builder_4_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(6709, 385, 'page_builder_4_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(6710, 385, '_page_builder_4_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(6711, 385, 'page_builder_4_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(6712, 385, '_page_builder_4_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(6713, 385, 'page_builder_4_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(6714, 385, '_page_builder_4_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(6715, 385, 'page_builder_4_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(6716, 385, '_page_builder_4_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(6717, 385, 'page_builder_4_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(6718, 385, '_page_builder_4_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(6719, 385, 'page_builder_4_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(6720, 385, '_page_builder_4_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
(6721, 385, 'page_builder_4_faq_items', '6'),
