(7051, 9, 'page_builder_4_process_tag', 'Standard Workflow'),
(7052, 9, '_page_builder_4_process_tag', 'field_6aa44a4f21cf6'),
(7053, 9, 'page_builder_4_process_title', 'Our 4-Step Canning Process'),
(7054, 9, '_page_builder_4_process_title', 'field_6aa44a6921cf7'),
(7055, 9, 'page_builder_4_process_description', 'Ensuring zero micro-flora activity and maximum natural nutrition retention.'),
(7056, 9, '_page_builder_4_process_description', 'field_6aa44a7621cf8'),
(7057, 9, 'page_builder_4_process_steps_0_step_number', '01'),
(7058, 9, '_page_builder_4_process_steps_0_step_number', 'field_6aa44a9521cfa'),
(7059, 9, 'page_builder_4_process_steps_0_step_title', 'Harvesting & Brix Inspection'),
(7060, 9, '_page_builder_4_process_steps_0_step_title', 'field_6aa44aa821cfb'),
(7061, 9, 'page_builder_4_process_steps_0_step_description', 'Hand-picked farm fresh fruit selection evaluated for peak maturity and natural Brix sweetness.'),
(7062, 9, '_page_builder_4_process_steps_0_step_description', 'field_6aa44ab621cfc'),
(7063, 9, 'page_builder_4_process_steps_1_step_number', '02'),
(7064, 9, '_page_builder_4_process_steps_1_step_number', 'field_6aa44a9521cfa'),
(7065, 9, 'page_builder_4_process_steps_1_step_title', 'Sterile Cold Pulping'),
(7066, 9, '_page_builder_4_process_steps_1_step_title', 'field_6aa44aa821cfb'),
(7067, 9, 'page_builder_4_process_steps_1_step_description', 'Mechanical pulp extraction under sterile cold-process without added synthetic colors or water dilution.'),
(7068, 9, '_page_builder_4_process_steps_1_step_description', 'field_6aa44ab621cfc'),
(7069, 9, 'page_builder_4_process_steps_2_step_number', '03'),
(7070, 9, '_page_builder_4_process_steps_2_step_number', 'field_6aa44a9521cfa'),
(7071, 9, 'page_builder_4_process_steps_2_step_title', 'Thermal Pasteurization'),
(7072, 9, '_page_builder_4_process_steps_2_step_title', 'field_6aa44aa821cfb'),
(7073, 9, 'page_builder_4_process_steps_2_step_description', 'Controlled thermal processing eliminating microbial activity while preserving natural fruit aroma.'),
(7074, 9, '_page_builder_4_process_steps_2_step_description', 'field_6aa44ab621cfc'),
(7075, 9, 'page_builder_4_process_steps_3_step_number', '04'),
