(7077, 9, 'page_builder_4_process_steps_3_step_title', 'Hermetic Seaming'),
(7078, 9, '_page_builder_4_process_steps_3_step_title', 'field_6aa44aa821cfb'),
(7079, 9, 'page_builder_4_process_steps_3_step_description', 'Vacuum double-seam tin capping or retort pouch sealing for long-term ambient shelf life.'),
(7080, 9, '_page_builder_4_process_steps_3_step_description', 'field_6aa44ab621cfc'),
(7081, 9, 'page_builder_4_process_steps', '4'),
(7082, 9, '_page_builder_4_process_steps', 'field_6aa44a8821cf9'),
(7083, 9, 'page_builder_5_faq_tag', 'Client Queries'),
(7084, 9, '_page_builder_5_faq_tag', 'field_6aa44c3bae1d2'),
(7085, 9, 'page_builder_5_faq_title', 'Frequently Asked Questions'),
(7086, 9, '_page_builder_5_faq_title', 'field_6aa44c49ae1d3'),
(7087, 9, 'page_builder_5_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(7088, 9, '_page_builder_5_faq_description', 'field_6aa44c59ae1d4'),
(7089, 9, 'page_builder_5_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(7090, 9, '_page_builder_5_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(7091, 9, 'page_builder_5_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(7092, 9, '_page_builder_5_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(7093, 9, 'page_builder_5_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(7094, 9, '_page_builder_5_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(7095, 9, 'page_builder_5_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(7096, 9, '_page_builder_5_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(7097, 9, 'page_builder_5_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(7098, 9, '_page_builder_5_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(7099, 9, 'page_builder_5_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(7100, 9, '_page_builder_5_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(7101, 9, 'page_builder_5_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(7102, 9, '_page_builder_5_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(7103, 9, 'page_builder_5_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(7104, 9, '_page_builder_5_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(7105, 9, 'page_builder_5_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(7106, 9, '_page_builder_5_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(7107, 9, 'page_builder_5_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(7108, 9, '_page_builder_5_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(7109, 9, 'page_builder_5_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(7110, 9, '_page_builder_5_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(7111, 9, 'page_builder_5_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(7112, 9, '_page_builder_5_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
