(7401, 386, 'page_builder_4_process_tag', 'Standard Workflow'),
(7402, 386, '_page_builder_4_process_tag', 'field_6aa44a4f21cf6'),
(7403, 386, 'page_builder_4_process_title', 'Our 4-Step Canning Process'),
(7404, 386, '_page_builder_4_process_title', 'field_6aa44a6921cf7'),
(7405, 386, 'page_builder_4_process_description', 'Ensuring zero micro-flora activity and maximum natural nutrition retention.'),
(7406, 386, '_page_builder_4_process_description', 'field_6aa44a7621cf8'),
(7407, 386, 'page_builder_4_process_steps_0_step_number', '01'),
(7408, 386, '_page_builder_4_process_steps_0_step_number', 'field_6aa44a9521cfa'),
(7409, 386, 'page_builder_4_process_steps_0_step_title', 'Harvesting & Brix Inspection'),
(7410, 386, '_page_builder_4_process_steps_0_step_title', 'field_6aa44aa821cfb'),
(7411, 386, 'page_builder_4_process_steps_0_step_description', 'Hand-picked farm fresh fruit selection evaluated for peak maturity and natural Brix sweetness.'),
(7412, 386, '_page_builder_4_process_steps_0_step_description', 'field_6aa44ab621cfc'),
(7413, 386, 'page_builder_4_process_steps_1_step_number', '02'),
(7414, 386, '_page_builder_4_process_steps_1_step_number', 'field_6aa44a9521cfa'),
(7415, 386, 'page_builder_4_process_steps_1_step_title', 'Sterile Cold Pulping'),
(7416, 386, '_page_builder_4_process_steps_1_step_title', 'field_6aa44aa821cfb'),
(7417, 386, 'page_builder_4_process_steps_1_step_description', 'Mechanical pulp extraction under sterile cold-process without added synthetic colors or water dilution.'),
(7418, 386, '_page_builder_4_process_steps_1_step_description', 'field_6aa44ab621cfc'),
(7419, 386, 'page_builder_4_process_steps_2_step_number', '03'),
(7420, 386, '_page_builder_4_process_steps_2_step_number', 'field_6aa44a9521cfa'),
(7421, 386, 'page_builder_4_process_steps_2_step_title', 'Thermal Pasteurization'),
(7422, 386, '_page_builder_4_process_steps_2_step_title', 'field_6aa44aa821cfb'),
(7423, 386, 'page_builder_4_process_steps_2_step_description', 'Controlled thermal processing eliminating microbial activity while preserving natural fruit aroma.'),
(7424, 386, '_page_builder_4_process_steps_2_step_description', 'field_6aa44ab621cfc'),
(7425, 386, 'page_builder_4_process_steps_3_step_number', '04'),
(7426, 386, '_page_builder_4_process_steps_3_step_number', 'field_6aa44a9521cfa'),
(7427, 386, 'page_builder_4_process_steps_3_step_title', 'Hermetic Seaming'),
(7428, 386, '_page_builder_4_process_steps_3_step_title', 'field_6aa44aa821cfb'),
(7429, 386, 'page_builder_4_process_steps_3_step_description', 'Vacuum double-seam tin capping or retort pouch sealing for long-term ambient shelf life.'),
(7430, 386, '_page_builder_4_process_steps_3_step_description', 'field_6aa44ab621cfc'),
(7431, 386, 'page_builder_4_process_steps', '4'),
(7432, 386, '_page_builder_4_process_steps', 'field_6aa44a8821cf9'),
(7433, 386, 'page_builder_5_faq_tag', 'Client Queries'),
(7434, 386, '_page_builder_5_faq_tag', 'field_6aa44c3bae1d2'),
(7435, 386, 'page_builder_5_faq_title', 'Frequently Asked Questions'),
(7436, 386, '_page_builder_5_faq_title', 'field_6aa44c49ae1d3'),
(7437, 386, 'page_builder_5_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(7438, 386, '_page_builder_5_faq_description', 'field_6aa44c59ae1d4'),
(7439, 386, 'page_builder_5_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(7440, 386, '_page_builder_5_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(7441, 386, 'page_builder_5_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(7442, 386, '_page_builder_5_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(7443, 386, 'page_builder_5_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(7444, 386, '_page_builder_5_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(7445, 386, 'page_builder_5_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(7446, 386, '_page_builder_5_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(7447, 386, 'page_builder_5_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(7448, 386, '_page_builder_5_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(7449, 386, 'page_builder_5_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(7450, 386, '_page_builder_5_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(7451, 386, 'page_builder_5_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(7452, 386, '_page_builder_5_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(7453, 386, 'page_builder_5_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(7454, 386, '_page_builder_5_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(7455, 386, 'page_builder_5_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(7456, 386, '_page_builder_5_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(7457, 386, 'page_builder_5_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(7458, 386, '_page_builder_5_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(7459, 386, 'page_builder_5_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(7460, 386, '_page_builder_5_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(7461, 386, 'page_builder_5_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(7462, 386, '_page_builder_5_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
