INSERT INTO `asc_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(7774, 388, '_page_builder_4_process_steps_1_step_description', 'field_6aa44ab621cfc'),
(7775, 388, 'page_builder_4_process_steps_2_step_number', '03'),
(7776, 388, '_page_builder_4_process_steps_2_step_number', 'field_6aa44a9521cfa'),
(7777, 388, 'page_builder_4_process_steps_2_step_title', 'Thermal Pasteurization'),
(7778, 388, '_page_builder_4_process_steps_2_step_title', 'field_6aa44aa821cfb'),
(7779, 388, 'page_builder_4_process_steps_2_step_description', 'Controlled thermal processing eliminating microbial activity while preserving natural fruit aroma.'),
(7780, 388, '_page_builder_4_process_steps_2_step_description', 'field_6aa44ab621cfc'),
(7781, 388, 'page_builder_4_process_steps_3_step_number', '04'),
(7782, 388, '_page_builder_4_process_steps_3_step_number', 'field_6aa44a9521cfa'),
(7783, 388, 'page_builder_4_process_steps_3_step_title', 'Hermetic Seaming'),
(7784, 388, '_page_builder_4_process_steps_3_step_title', 'field_6aa44aa821cfb'),
(7785, 388, 'page_builder_4_process_steps_3_step_description', 'Vacuum double-seam tin capping or retort pouch sealing for long-term ambient shelf life.'),
(7786, 388, '_page_builder_4_process_steps_3_step_description', 'field_6aa44ab621cfc'),
(7787, 388, 'page_builder_4_process_steps', '4'),
(7788, 388, '_page_builder_4_process_steps', 'field_6aa44a8821cf9'),
(7789, 388, 'page_builder_5_faq_tag', 'Client Queries'),
(7790, 388, '_page_builder_5_faq_tag', 'field_6aa44c3bae1d2'),
(7791, 388, 'page_builder_5_faq_title', 'Frequently Asked Questions'),
(7792, 388, '_page_builder_5_faq_title', 'field_6aa44c49ae1d3'),
(7793, 388, 'page_builder_5_faq_description', 'Answers regarding FSSAI compliance, minimum batch sizes, and contract processing.'),
(7794, 388, '_page_builder_5_faq_description', 'field_6aa44c59ae1d4'),
(7795, 388, 'page_builder_5_faq_items_0_faq_question', 'What is the minimum batch size for custom contract canning?'),
(7796, 388, '_page_builder_5_faq_items_0_faq_question', 'field_6aa44c79ae1d6'),
(7797, 388, 'page_builder_5_faq_items_0_faq_answer', 'We cater to small-scale farmers and cottage preservers starting from 25 KG batches up to commercial production runs of 1,000+ KG per day.'),
(7798, 388, '_page_builder_5_faq_items_0_faq_answer', 'field_6aa44c8bae1d7'),
(7799, 388, 'page_builder_5_faq_items_1_faq_question', 'Is FSSAI certification included for packed items?'),
(7800, 388, '_page_builder_5_faq_items_1_faq_question', 'field_6aa44c79ae1d6'),
(7801, 388, 'page_builder_5_faq_items_1_faq_answer', 'Yes, all processing and hermetic canning is executed under Asal Canning Center\'s FSSAI License No. 10718026000263 following strict hygiene and thermal pasteurization rules.'),
(7802, 388, '_page_builder_5_faq_items_1_faq_answer', 'field_6aa44c8bae1d7'),
(7803, 388, 'page_builder_5_faq_items_2_faq_question', 'Do you offer packaging options for export orders?'),
(7804, 388, '_page_builder_5_faq_items_2_faq_question', 'field_6aa44c79ae1d6'),
(7805, 388, 'page_builder_5_faq_items_2_faq_answer', 'Yes, we support hermetic tin canning (850g), retort pouch packing (1kg), glass bottles (500g), and ceramic jar packing suitable for international transport and long-term shelf storage.'),
(7806, 388, '_page_builder_5_faq_items_2_faq_answer', 'field_6aa44c8bae1d7'),
(7807, 388, 'page_builder_5_faq_items_3_faq_question', 'How are fruit pulps preserved without artificial chemicals?'),
(7808, 388, '_page_builder_5_faq_items_3_faq_question', 'field_6aa44c79ae1d6'),
(7809, 388, 'page_builder_5_faq_items_3_faq_answer', 'We utilize thermal pasteurization, hermetic double-seam vacuum sealing, and flash freezing. This eliminates microbial activity while preserving 100% natural fruit taste, color, and nutrient profile without added chemical preservatives.'),
(7810, 388, '_page_builder_5_faq_items_3_faq_answer', 'field_6aa44c8bae1d7'),
(7811, 388, 'page_builder_5_faq_items_4_faq_question', 'Can I request custom private label packaging for my food brand?'),
(7812, 388, '_page_builder_5_faq_items_4_faq_question', 'field_6aa44c79ae1d6'),
(7813, 388, 'page_builder_5_faq_items_4_faq_answer', 'Absolutely. We offer white-label contract processing and custom pouch/can/jar labeling with full regulatory compliance and nutritional breakdown for domestic and export markets.'),
(7814, 388, '_page_builder_5_faq_items_4_faq_answer', 'field_6aa44c8bae1d7'),
(7815, 388, 'page_builder_5_faq_items_5_faq_question', 'Where is Asal Canning Center located & what are facility visiting hours?'),
(7816, 388, '_page_builder_5_faq_items_5_faq_question', 'field_6aa44c79ae1d6'),
(7817, 388, 'page_builder_5_faq_items_5_faq_answer', 'We are located in Paldi, Ahmedabad, Gujarat. Visitors and clients are welcome Monday through Saturday from 9:00 AM to 7:00 PM for facility tours and batch consultations.'),
(7818, 388, '_page_builder_5_faq_items_5_faq_answer', 'field_6aa44c8bae1d7'),
